import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CD2m2Tvf.js";const g=JSON.parse('{"title":"Step-by-Step Build Order & Implementation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"02-build-order.md","filePath":"02-build-order.md"}'),i={name:"02-build-order.md"};function r(l,e,s,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="step-by-step-build-order-implementation-guide" tabindex="-1">Step-by-Step Build Order &amp; Implementation Guide <a class="header-anchor" href="#step-by-step-build-order-implementation-guide" aria-label="Permalink to &quot;Step-by-Step Build Order &amp; Implementation Guide&quot;">​</a></h1><p>This guide details the exact chronological sequence to reconstruct <strong>14-Tracing-Backend</strong> from scratch.</p><hr><h2 id="phase-1-core-foundation-data-modeling" tabindex="-1">Phase 1: Core Foundation &amp; Data Modeling <a class="header-anchor" href="#phase-1-core-foundation-data-modeling" aria-label="Permalink to &quot;Phase 1: Core Foundation &amp; Data Modeling&quot;">​</a></h2><ol><li><strong>Initialize Database Schema</strong>: Define the primary <code>spans</code> and <code>traces</code> tables using SQLAlchemy models (<code>backend/src/storage/models.py</code>). Index <code>trace_id</code>, <code>service_name</code>, and <code>start_time_us</code>.</li><li><strong>FastAPI Application Setup</strong>: Scaffold <code>backend/src/api/app.py</code> with standard middleware, health probes (<code>/healthz</code>, <code>/readyz</code>), and centralized HTTP error formatting.</li><li><strong>Trace Context Propagation</strong>: Implement W3C <code>traceparent</code> parsing in <code>backend/src/tracelib/core/</code> to extract <code>trace_id</code>, <code>span_id</code>, and sampling flags.</li></ol><hr><h2 id="phase-2-ingestion-collector-pipeline" tabindex="-1">Phase 2: Ingestion &amp; Collector Pipeline <a class="header-anchor" href="#phase-2-ingestion-collector-pipeline" aria-label="Permalink to &quot;Phase 2: Ingestion &amp; Collector Pipeline&quot;">​</a></h2><ol start="4"><li><strong>OTLP Ingestion Endpoints</strong>: Build <code>api/routes/ingestion.py</code> supporting OpenTelemetry Protobuf and JSON payloads.</li><li><strong>PII Sanitizer &amp; Security Redaction</strong>: Implement regex and key-name scanners in <code>security/pii_filter.py</code> to strip passwords, credit card numbers, and authorization tokens.</li><li><strong>Asynchronous Ring Buffer</strong>: Implement bounded queue management in <code>collector/queue_buffer.py</code> with background batch-flushing workers.</li></ol><hr><h2 id="phase-3-adaptive-sampling-engine" tabindex="-1">Phase 3: Adaptive Sampling Engine <a class="header-anchor" href="#phase-3-adaptive-sampling-engine" aria-label="Permalink to &quot;Phase 3: Adaptive Sampling Engine&quot;">​</a></h2><ol start="7"><li><strong>Tail-Sampling Sliding Window</strong>: Build <code>sampling/tail_window.py</code> holding uncompleted trace spans for up to 30 seconds.</li><li><strong>Error &amp; Latency Evaluators</strong>: Wire <code>sampling/error_aware.py</code> and <code>sampling/tail.py</code> to promote traces with HTTP errors or duration exceeding p99 thresholds.</li></ol><hr><h2 id="phase-4-query-engine-graph-traversal" tabindex="-1">Phase 4: Query Engine &amp; Graph Traversal <a class="header-anchor" href="#phase-4-query-engine-graph-traversal" aria-label="Permalink to &quot;Phase 4: Query Engine &amp; Graph Traversal&quot;">​</a></h2><ol start="9"><li><strong>Trace Reconstruction</strong>: Build <code>query/trace_lookup.py</code> to assemble unordered spans into an execution tree.</li><li><strong>Critical Path Calculation</strong>: Implement DAG topological sorting in <code>query/critical_path.py</code> to isolate blocking sequential spans.</li></ol><hr><h2 id="phase-5-machine-learning-llm-integration" tabindex="-1">Phase 5: Machine Learning &amp; LLM Integration <a class="header-anchor" href="#phase-5-machine-learning-llm-integration" aria-label="Permalink to &quot;Phase 5: Machine Learning &amp; LLM Integration&quot;">​</a></h2><ol start="11"><li><strong>Anomaly Detectors</strong>: Implement <code>ml/latency_anomaly.py</code> and <code>ml/dependency_anomaly.py</code> using statistical z-scores.</li><li><strong>Pre-trained LLM Postmortem Engine</strong>: Connect <code>ml/llm_engine.py</code> to external LLM API with strict JSON schema parsing.</li></ol><hr><h2 id="phase-6-frontend-visualization-react-18-vite" tabindex="-1">Phase 6: Frontend Visualization (React 18 + Vite) <a class="header-anchor" href="#phase-6-frontend-visualization-react-18-vite" aria-label="Permalink to &quot;Phase 6: Frontend Visualization (React 18 + Vite)&quot;">​</a></h2><ol start="13"><li><strong>Vite Scaffold</strong>: Set up React 18, TypeScript, and Tailwind CSS in <code>frontend/</code>.</li><li><strong>Gantt Waterfall &amp; DAG Tree</strong>: Implement <code>WaterfallTimeline.tsx</code> and <code>SpanTree.tsx</code> to visualize parallel and critical path execution.</li></ol>',20)])])}const m=a(i,[["render",r]]);export{g as __pageData,m as default};
